public void logEvent(String userId, String eventType, long timestamp) {
        if (!userEvents.containsKey(userId)) {
            userEvents.put(userId, new ArrayList<>());
        }
        userEvents.get(userId).add(new Event(eventType, timestamp));

        // Attempting to update total counts per user per event type
        Map<String, Integer> counts = userEventCounts.get(userId);
        if (counts == null) {
            counts = new HashMap<>();
            // Bug 1: Missing put back into outer map!
        }
        counts.put(eventType, counts.getOrDefault(eventType, 0) + 1);
    }

    public int queryWindowFrequency(String userId, String targetEventType, long windowSize, long currentTime) {
        long minTime = currentTime - windowSize;

        List<Event> events = userEvents.get(userId);
        int count = 0;

        for (Event e : events) {
            if (e.type.equals(targetEventType) && e.timestamp > minTime && e.timestamp <= currentTime) {
                count++;
            }
        }
        return count;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;
        int n = sc.nextInt();

        Main tracker = new Main();

        for (int i = 0; i < n; i++) {
            String op = sc.next();
            if (op.equals("LOG")) {
                String uId = sc.next();
                String eType = sc.next();
                long ts = sc.nextLong();
                tracker.logEvent(uId, eType, ts);
            } else if (op.equals("QUERY")) {
                String uId = sc.next();
                String targetType = sc.next();
                long wSize = sc.nextLong();
                long curTime = sc.nextLong();
                System.out.println(tracker.queryWindowFrequency(uId, targetType, wSize, curTime));
            }
        }
        sc.close();
    }
}

